/**
 * Sub-issue tree rules: the tree never loops and nothing sits deeper than
 * `MAX_SUB_ISSUE_DEPTH`, a root issue being level 0.
 *
 * The service layer gathers the facts (the lineage a placement would join, the
 * depth of the sub-issues below an issue); these helpers decide whether the
 * placement is allowed and name the refusal when it is not.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export type IssueHierarchyReason = "cycle" | "too_deep";

/** Raised when a placement would loop the tree or push a sub-issue too deep; mapped to `conflict`. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or under its own sub-issues`
        : `Issue ${issueId} would sit deeper than level ${MAX_SUB_ISSUE_DEPTH}`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * Refuses a placement whose new parent chain already holds the issue.
 * `parentLineage` is the proposed parent followed by its ancestors, so meeting
 * the issue there means the placement would close a loop.
 */
export function assertNoCycle(
  issueId: string,
  parentLineage: readonly string[],
): void {
  if (parentLineage.includes(issueId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }
}

/**
 * Refuses a placement that would leave any sub-issue below the depth limit.
 * `level` is where the issue itself lands; `deepestBelow` is how many levels of
 * sub-issues hang under it, zero when it has none.
 */
export function assertWithinDepth(
  issueId: string,
  level: number,
  deepestBelow: number,
): void {
  if (level + deepestBelow > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

