 */
function subtreeCte(orgId: OrgId, rootId: IssueId): SQL {
  return sql`WITH RECURSIVE subtree(id, archived_at, status, depth) AS (
    SELECT d.id, d.archived_at, d.status, 1 FROM issues AS d
    WHERE d.org_id = ${orgId} AND d.parent_id = ${rootId}
