  IssueWithRelations,
} from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after five gates: tenant scope, the `issue:create`
 * permission, a live parent in the same project (when one is given), the depth
 * limit and the plan's per-project issue quota. Only then is a number allocated
 * and `issue.created` published — everything reactive (notifications, search,
 * webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  // Chosen up front so a refused depth check can still name the issue it refused.
  const issueId = newId() as IssueId;
  const parentLineage = await parentLineageFor(
    input.orgId,
    project.id,
    input.parentId,
  );
  assertWithinDepth(issueId, parentLineage.length, 0);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number, issueId);

