/**
 * Archives the issue together with every live issue below it. Each one is
 * announced with its own `issue.archived`, so downstream counters and the search
 * index treat the whole tree like individual archives. The parent is untouched.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const tree = await issueRepo.archiveIssueTree(orgId, issueId);
  const archived = requireFound(
    tree.find((row) => row.id === issueId),
    "Issue",
    issueId,
  );

  for (const row of [archived, ...tree.filter((row) => row.id !== issueId)]) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  return archived;
}

/**
 * Places an issue under a live parent of its own project, moves it to another
 * parent, or makes it a root again (`parentId: null`). The sub-issues below it
 * move with it, so the cycle and depth rules are judged on the whole subtree.
 * Nothing is written or announced when a rule refuses the move.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.parentId === before.parentId) return before;

  const parentLineage = await parentLineageFor(
    input.orgId,
    before.projectId,
    input.parentId,
  );
  assertNoCycle(before.id, parentLineage);

  const { deepest } = await issueRepo.summarizeSubtree(input.orgId, before.id);
  assertWithinDepth(before.id, parentLineage.length, deepest);

  const after = await issueRepo.setIssueParent(
    input.orgId,
    before.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct sub-issues that are not archived, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listDirectSubIssues(orgId, issue.id);
}

/** Live sub-issues below an issue at any depth, split into open and closed. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const { total, open, closed } = await issueRepo.summarizeSubtree(
    orgId,
    issue.id,
  );
  return { total, open, closed };
}

/**
 * A parent must be a live issue of the same project in this workspace. Anything
 * else reads as not found, so a foreign id reveals nothing about itself.
 */
async function requireParentInProject(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * The chain a placement would join: the parent, then its ancestors. A root
 * placement joins nothing. The chain's length is the level the placed issue
 * would sit at, since a root is level 0.
 */
async function parentLineageFor(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<readonly IssueId[]> {
  if (parentId === null) return [];
  const parent = await requireParentInProject(orgId, projectId, parentId);
  return lineageOf(orgId, parent.id);
}

/**
 * The chain from `issueId` up to its root, `issueId` first. The walk stops at a
 * repeated id, so a corrupt loop in stored data cannot hang the request.
 */
async function lineageOf(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const lineage: IssueId[] = [];
  let cursor: IssueId | null = issueId;
  while (cursor !== null && !lineage.includes(cursor)) {
    lineage.push(cursor);
    cursor = (await issueRepo.findIssueById(orgId, cursor))?.parentId ?? null;
  }
  return lineage;
}

