async function parentLineageFor(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<readonly IssueId[]> {
  if (parentId === null) return [];
  const parent = await requireParentInProject(orgId, projectId, parentId);
