/**
 * Sub-issues: placement, the cycle and depth rules, listing, the roll-up, the
 * archive cascade and the completion notice sent to a parent's assignee.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hierarchy");
});

afterAll(() => {
  cleanup();
});

/** Creates an issue in the tenant's project, optionally under a parent and for an assignee. */
function create(
  title: string,
  parent: Issue | null = null,
  assigneeId: UserId | null = null,
  actor: Actor = tenant.actors.member,
) {
  return issueService.createIssue(actor, {
    ...issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }),
    parentId: parent?.id ?? null,
  });
}

function place(
  issue: Issue,
  parent: Issue | null,
  actor: Actor = tenant.actors.member,
) {
  return issueService.setIssueParent(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    parentId: parent?.id ?? null,
  });
}

function setStatus(
  issue: Issue,
  status: IssueStatus,
  actor: Actor = tenant.actors.member,
) {
  return issueService.changeIssueStatus(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    status,
  });
}

/** The error a rejected attempt settled with; fails the test if the attempt succeeded. */
async function refusalOf(attempt: Promise<unknown>): Promise<unknown> {
  return attempt.then(
    () => {
      throw new Error("expected the attempt to be refused");
    },
    (error: unknown) => error,
  );
}

async function noticesFor(recipientId: UserId): Promise<number> {
  const page = await notificationService.listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.total;
}

describe("services/issue-service — setIssueParent", () => {
  it("places an issue under a parent of its project and announces the move", async () => {
    const parent = await create("Epic for placement");
    const child = await create("Child to place");

    const seen: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => {
      seen.push(payload);
    });

    try {
      const placed = await place(child, parent);

      expect(placed.parentId).toBe(parent.id);
      expect(seen).toHaveLength(1);
      expect(seen[0]).toMatchObject({ issueId: child.id, changedFields: ["parentId"] });
    } finally {
      off();
    }
  });

  it("moves a sub-issue with the sub-issues below it, and can make it a root again", async () => {
    const top = await create("Top for detach");
    const mid = await create("Mid for detach", top);
    const leaf = await create("Leaf for detach", mid);
    const elsewhere = await create("Elsewhere for detach");

    await place(mid, elsewhere);

    expect((await issueRepo.findIssueById(tenant.org.id, mid.id))?.parentId).toBe(elsewhere.id);
    expect((await issueRepo.findIssueById(tenant.org.id, leaf.id))?.parentId).toBe(mid.id);

    const detached = await place(mid, null);
    expect(detached.parentId).toBeNull();
  });

  it("refuses to place an issue under itself or under anything below it", async () => {
    const top = await create("Cycle top");
    const sub = await create("Cycle sub", top);
    const deeper = await create("Cycle deeper", sub);

    expect(await refusalOf(place(top, top))).toBeInstanceOf(IssueHierarchyError);
    expect(await refusalOf(place(top, deeper))).toMatchObject({ reason: "cycle" });
    expect(await refusalOf(place(top, sub))).toMatchObject({ reason: "cycle" });
    expect((await issueRepo.findIssueById(tenant.org.id, top.id))?.parentId).toBeNull();
  });

  it("refuses a move that would leave any sub-issue below the depth limit, and changes nothing", async () => {
    const root = await create("Depth root");
    const a = await create("Depth a", root);
    const b = await create("Depth b", a);
    const c = await create("Depth c", b);

    const otherRoot = await create("Depth other root");
    const otherChild = await create("Depth other child", otherRoot);

    // `root` carries three levels of sub-issues, so it may only sit at the top.
    expect(await refusalOf(place(root, otherRoot))).toMatchObject({ reason: "too_deep" });
    expect(await refusalOf(place(root, otherChild))).toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, root.id))?.parentId).toBeNull();

    // `a` carries two levels, so it fits one level down and no lower.
    expect(await refusalOf(place(a, otherChild))).toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, a.id))?.parentId).toBe(root.id);

    const moved = await place(a, otherRoot);
    expect(moved.parentId).toBe(otherRoot.id);
    expect((await issueRepo.findIssueById(tenant.org.id, c.id))?.parentId).toBe(b.id);
  });

  it("treats a parent from another project or another workspace as not found", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch hierarchy",
      slug: "scratch-hierarchy",
      key: "SCH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Issue of another project" }),
    );
    const child = await create("Needs a same-project parent");

    expect(await refusalOf(place(child, elsewhere))).toBeInstanceOf(NotFoundError);

    const north = await createTenant("hierarchy-north");
    const foreign = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Issue of another workspace" }),
    );

    expect(await refusalOf(place(child, foreign))).toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent, and refuses to move an archived issue", async () => {
    const gone = await create("Archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);
    const child = await create("Child of an archived parent");

    expect(await refusalOf(place(child, gone))).toBeInstanceOf(AlreadyArchivedError);

    const archivedChild = await create("Archived child");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedChild.id);

    expect(await refusalOf(place(archivedChild, child))).toBeInstanceOf(AlreadyArchivedError);
  });

  it("requires issue:update on the issue and keeps the caller inside their workspace", async () => {
    const parent = await create("Permission parent");
    const child = await create("Permission child");

    expect(await refusalOf(place(child, parent, tenant.actors.viewer))).toBeInstanceOf(
      PermissionDeniedError,
    );

    const other = await createTenant("hierarchy-acme");
    await expect(
      issueService.setIssueParent(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — sub-issues at creation", () => {
  it("creates nothing and announces nothing when the parent is refused", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Creation hierarchy",
      slug: "creation-hierarchy",
      key: "CRH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Parent in another project" }),
    );

    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const seen: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      seen.push(payload);
    });

    try {
      expect(
        await refusalOf(create("Refused sub-issue", elsewhere)),
      ).toBeInstanceOf(NotFoundError);
      expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
      expect(seen).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("refuses a sub-issue that would sit below the depth limit", async () => {
    const root = await create("Creation depth root");
    const a = await create("Creation depth a", root);
    const b = await create("Creation depth b", a);
    const c = await create("Creation depth c", b);

    expect(await refusalOf(create("Creation depth d", c))).toMatchObject({
      reason: "too_deep",
    });
  });
});

describe("services/issue-service — listing and roll-up", () => {
  it("lists live direct sub-issues oldest first", async () => {
    const parent = await create("Listing parent");
    const first = await create("Listing first", parent);
    const second = await create("Listing second", parent);
    const third = await create("Listing third", parent);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, second.id);
    await create("Listing grandchild", first);

    const listed = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      parent.id,
    );

    expect(listed.map((issue) => issue.id)).toEqual([first.id, third.id]);
  });

  it("rolls up live sub-issues at every depth and leaves archived ones out", async () => {
    const parent = await create("Roll-up parent");
    const done = await create("Roll-up done", parent);
    const open = await create("Roll-up open", parent);
    const deepOpen = await create("Roll-up deep open", open);
    const deepCanceled = await create("Roll-up deep canceled", done);
    await setStatus(done, "done");
    await setStatus(deepCanceled, "canceled");
    await setStatus(deepOpen, "in_progress");

    const archived = await create("Roll-up archived", parent);
    await create("Roll-up archived child", archived);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, parent.id),
    ).resolves.toEqual({ total: 4, open: 2, closed: 2 });
  });

  it("counts more sub-issues than one page holds", async () => {
    const parent = await create("Wide parent");
    for (let index = 0; index < 120; index += 1) {
      await create(`Wide child ${index}`, parent);
    }

    const rollup = await issueService.getIssueRollup(
      tenant.actors.member,
      tenant.org.id,
      parent.id,
    );
    expect(rollup).toEqual({ total: 120, open: 120, closed: 0 });
  });

  it("refuses reads of an issue from another workspace or with a foreign orgId", async () => {
    const north = await createTenant("hierarchy-south");
    const foreign = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "South only" }),
    );

    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssueRollup(tenant.actors.member, north.org.id, foreign.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — archive cascade", () => {
  it("archives the live sub-issues at any depth, announcing each one, and leaves the parent alone", async () => {
    const root = await create("Cascade root");
    const kept = await create("Cascade kept", root);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, kept.id);
    const keptBefore = await issueRepo.findIssueById(tenant.org.id, kept.id);

    const mid = await create("Cascade mid", root);
    const leaf = await create("Cascade leaf", mid);
    const outside = await create("Cascade outside");

    const announced: IssueId[] = [];
    const off = subscribe("issue.archived", (payload) => {
      announced.push(payload.issueId);
    });

    try {
      const archived = await issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        root.id,
      );
      expect(archived.archivedAt).not.toBeNull();
    } finally {
      off();
    }

    expect([...announced].sort()).toEqual([root.id, mid.id, leaf.id].sort());
    expect(announced[0]).toBe(root.id);

    const keptAfter = await issueRepo.findIssueById(tenant.org.id, kept.id);
    expect(keptAfter?.archivedAt).toBe(keptBefore?.archivedAt);
    expect((await issueRepo.findIssueById(tenant.org.id, leaf.id))?.archivedAt).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, outside.id))?.archivedAt).toBeNull();
  });

  it("archiving a sub-issue never touches its parent", async () => {
    const parent = await create("Survivor parent");
    const child = await create("Doomed child", parent);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect((await issueRepo.findIssueById(tenant.org.id, parent.id))?.archivedAt).toBeNull();
  });
});

describe("services/issue-service — completion notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const parent = await create("Notice parent", null, tenant.userIds.admin);
    const first = await create("Notice first", parent);
    const second = await create("Notice second", parent);
    const before = await noticesFor(tenant.userIds.admin);

    await setStatus(first, "done");
    expect(await noticesFor(tenant.userIds.admin)).toBe(before);

    await setStatus(second, "canceled");
    expect(await noticesFor(tenant.userIds.admin)).toBe(before + 1);

    // Closed to another closed status is not a closing.
    await setStatus(second, "done");
    expect(await noticesFor(tenant.userIds.admin)).toBe(before + 1);

    // Reopening and closing again tells the assignee again.
    await setStatus(first, "todo");
    await setStatus(first, "done");
    expect(await noticesFor(tenant.userIds.admin)).toBe(before + 2);
  });

  it("does not tell the person who closed the last sub-issue", async () => {
    const parent = await create("Self parent", null, tenant.userIds.admin);
    const only = await create("Self only", parent);
    const before = await noticesFor(tenant.userIds.admin);

    await setStatus(only, "done", tenant.actors.admin);

    expect(await noticesFor(tenant.userIds.admin)).toBe(before);
  });

  it("counts archiving the last open sub-issue as completion, and archiving a closed one as nothing", async () => {
    const parent = await create("Archive notice parent", null, tenant.userIds.owner);
    const open = await create("Archive notice open", parent);
    const before = await noticesFor(tenant.userIds.owner);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, open.id);
    expect(await noticesFor(tenant.userIds.owner)).toBe(before + 1);

    const quietParent = await create("Archive notice quiet", null, tenant.userIds.owner);
    const closed = await create("Archive notice closed", quietParent);
    await setStatus(closed, "done");
    const afterClosing = await noticesFor(tenant.userIds.owner);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, closed.id);

    expect(await noticesFor(tenant.userIds.owner)).toBe(afterClosing);
  });

  it("stays silent when an open sub-issue is moved away", async () => {
    const parent = await create("Moving notice parent", null, tenant.userIds.admin);
    const moving = await create("Moving notice child", parent);
    const before = await noticesFor(tenant.userIds.admin);

    await place(moving, null);

    expect(await noticesFor(tenant.userIds.admin)).toBe(before);
  });
});

